12	export function runCli(args, { input, cwd } = {}) {
13	  const result = spawnSync(process.execPath, [CLI, ...args], {
14	    input: input === undefined ? '' : input,
15	    cwd,
16	    maxBuffer: 64 * 1024 * 1024,
17	  });
18	  if (result.error && result.error.code !== 'EPIPE') throw result.error;
19	  return {
20	    status: result.status,
21	    stdout: result.stdout ? result.stdout.toString('utf8') : '',
22	    stderr: result.stderr ? result.stderr.toString('utf8') : '',
23	  };
24	}
