17	    ['/~1~11', ['//1']],
18	    ['/\u0000\r\n', ['\u0000\r\n']],
19	    ['/a~1b', ['a/b']],
20	    ['/~0', ['~']],
21	    ['/é/日本', ['é', '日本']],
22	    ['/a b', ['a b']],
