10	const fail = (doc, ops, reason, i = 0) =>
11	  expectPatchError(() => applyPatch(doc, ops), `operation ${i}: ${reason}`, i);
12	const failOp = (doc, op, reason) => fail(doc, [op], reason);
13	const ap = (doc, ...ops) => applyPatch(doc, ops);
14	const keys = (x) => Object.keys(x);
