16	describe('own-member lookup', () => {
17	  for (const name of ['__proto__', 'constructor', 'toString', 'hasOwnProperty', 'valueOf']) {
18	    test(`test on {} at /${name} is path not found`, () => {
19	      failOp({}, { op: 'test', path: `/${name}`, value: 1 }, PNF);
20	    });
21	  }
22	
23	  test('remove /toString on {}', () => {
24	    failOp({}, { op: 'remove', path: '/toString' }, PNF);
25	  });
26	
27	  test('replace /constructor on {} is path not found', () => {
28	    failOp({}, { op: 'replace', path: '/constructor', value: 1 }, PNF);
29	  });
30	
31	  test('own __proto__ and constructor members are found', () => {
32	    const doc = JSON.parse('{"__proto__":1,"constructor":2}');
33	    assert.deepEqual(ap(doc, { op: 'test', path: '/__proto__', value: 1 }), doc);
34	    assert.deepEqual(ap(doc, { op: 'test', path: '/constructor', value: 2 }).constructor, 2);
35	  });
36	
37	  test('replace /__proto__ gives an own member', () => {
38	    const doc = JSON.parse('{"__proto__":1,"constructor":2}');
39	    const result = ap(doc, { op: 'replace', path: '/__proto__', value: 5 });
40	    assert.ok(Object.hasOwn(result, '__proto__'));
41	    assert.equal(Object.getOwnPropertyDescriptor(result, '__proto__').value, 5);
42	    assert.equal(Object.getPrototypeOf(result), Object.prototype);
43	  });
44	
45	  test('add /__proto__ on {} creates an own member', () => {
46	    const result = ap({}, { op: 'add', path: '/__proto__', value: { x: 1 } });
47	    assert.equal(Object.getPrototypeOf(result), Object.prototype);
48	    assert.equal(result.x, undefined);
49	    assert.deepEqual(keys(result), ['__proto__']);
50	    assert.deepEqual(Object.getOwnPropertyDescriptor(result, '__proto__').value, { x: 1 });
51	  });
52	
53	  test('copy and move from /constructor on {} is from not found', () => {
54	    failOp({}, { op: 'copy', from: '/constructor', path: '/a' }, FNF);
55	    failOp({}, { op: 'move', from: '/constructor', path: '/a' }, FNF);
