5	// Records structure, key order and values so changes are detectable.
6	function snapshot(value) {
7	  return { clone: structuredClone(value), order: orderOf(value) };
8	}
9	
10	function orderOf(value) {
11	  if (Array.isArray(value)) return value.map(orderOf);
12	  if (value !== null && typeof value === 'object') {
13	    return Object.keys(value).map((k) => [k, orderOf(value[k])]);
14	  }
15	  return Object.is(value, -0) ? '-0' : value;
16	}
17	
18	function assertUnchanged(value, snap) {
19	  assert.deepEqual(value, snap.clone);
20	  assert.deepEqual(orderOf(value), snap.order);
21	}
22	
23	// Runs applyPatch and checks doc and patch are untouched whether or not it throws.
24	function applyChecked(doc, patch) {
25	  const d = snapshot(doc);
26	  const p = snapshot(patch);
27	  try {
28	    return applyPatch(doc, patch);
29	  } catch (err) {
30	    assert.ok(err instanceof PatchError);
31	    return err;
32	  } finally {
33	    assertUnchanged(doc, d);
34	    assertUnchanged(patch, p);
35	  }
36	}
