38	function collect(value, set = new Set()) {
39	  if (value !== null && typeof value === 'object') {
40	    set.add(value);
41	    for (const k of Object.keys(value)) collect(value[k], set);
42	  }
43	  return set;
44	}
45	
46	function assertNoSharing(result, doc, patch) {
47	  const mine = collect(result);
48	  const theirs = collect(patch, collect(doc));
49	  for (const obj of mine) assert.ok(!theirs.has(obj), 'result shares an object with doc or patch');
50	}
